void ThermostatUi::refresh_all() {
  char buffer[16];

  format_temp_celsius(vm_.current_temp_centi, vm_.temp_valid, buffer,
                      sizeof(buffer));
  lv_label_set_text(current_temp_label_, buffer);

  format_temp_celsius(vm_.target_temp_centi, true, buffer, sizeof(buffer));
  lv_label_set_text(target_temp_label_, buffer);

  lv_label_set_text(heating_label_, vm_.heating_active ? "난방 중" : "대기");
  lv_obj_set_style_bg_color(
      heating_badge_,
      lv_color_hex(vm_.heating_active ? kColorAccent : kColorBadgeIdle), 0);
  lv_obj_set_style_text_color(
      heating_label_,
      lv_color_hex(vm_.heating_active ? kColorTextOnAccent : kColorMuted), 0);

  refresh_source_badge();
  refresh_mode_buttons();
  refresh_settings_values();

  lv_label_set_text(time_label_, vm_.time_text);
}

void ThermostatUi::refresh_source_badge() {
  lv_label_set_text(source_label_, vm_.source_text);
  const uint32_t color = severity_color(vm_.source_severity);
  lv_obj_set_style_text_color(source_label_, lv_color_hex(color), 0);
  lv_obj_set_style_border_color(source_badge_, lv_color_hex(color), 0);
}

void ThermostatUi::refresh_mode_buttons() {
  const int selected = static_cast<int>(vm_.mode);
  for (int index = 0; index < 3; ++index) {
    apply_button_style(mode_buttons_[index], index == selected);
  }
}

void ThermostatUi::refresh_settings_values() {
  char buffer[16];
  std::snprintf(buffer, sizeof(buffer), "%u분",
                static_cast<unsigned>(vm_.repeat_on_minutes));
  lv_label_set_text(repeat_value_label_, buffer);

  format_temp_celsius(vm_.freeze_protect_centi, true, buffer, sizeof(buffer));
  lv_label_set_text(freeze_value_label_, buffer);
}

void ThermostatUi::on_clicked(lv_event_t* event) {
  auto* self = static_cast<ThermostatUi*>(lv_event_get_user_data(event));
  auto* target = static_cast<lv_obj_t*>(lv_event_get_current_target(event));
  if (self == nullptr || target == nullptr) {
    return;
  }
  self->handle_action(
      static_cast<Action>(user_data_action(lv_obj_get_user_data(target))));
}

void ThermostatUi::handle_action(Action action) {
  switch (action) {
    case Action::kTargetMinus:
    case Action::kTargetPlus: {
      const int16_t next = step_target_temp(
          vm_.target_temp_centi,
          action == Action::kTargetPlus ? kTargetStepCenti : -kTargetStepCenti);
      if (next != vm_.target_temp_centi) {
        vm_.target_temp_centi = next;
        char buffer[16];
        format_temp_celsius(next, true, buffer, sizeof(buffer));
        lv_label_set_text(target_temp_label_, buffer);
        if (callbacks_.on_target_temp_change != nullptr) {
          callbacks_.on_target_temp_change(next, callbacks_.ctx);
        }
      }
      break;
    }
    case Action::kModeOff:
    case Action::kModeTemperature:
    case Action::kModeRepeat: {
      UiMode next = UiMode::kOff;
      if (action == Action::kModeTemperature) {
        next = UiMode::kTemperature;
      } else if (action == Action::kModeRepeat) {
        next = UiMode::kRepeat;
      }
      if (next != vm_.mode) {
        vm_.mode = next;
        refresh_mode_buttons();
        if (callbacks_.on_mode_change != nullptr) {
          callbacks_.on_mode_change(next, callbacks_.ctx);
        }
      }
      break;
    }
    case Action::kOpenSettings:
      show_settings(true);
      break;
    case Action::kCloseSettings:
      show_settings(false);
      break;
    case Action::kRepeatMinus:
    case Action::kRepeatPlus: {
      const uint8_t next = step_repeat_minutes(
          vm_.repeat_on_minutes,
          action == Action::kRepeatPlus ? kRepeatStepMinutes
                                        : -kRepeatStepMinutes);
      if (next != vm_.repeat_on_minutes) {
        vm_.repeat_on_minutes = next;
        refresh_settings_values();
        if (callbacks_.on_repeat_minutes_change != nullptr) {
          callbacks_.on_repeat_minutes_change(next, callbacks_.ctx);
        }
      }
      break;
    }
    case Action::kFreezeMinus:
    case Action::kFreezePlus: {
      const int16_t next = step_freeze_protect(
          vm_.freeze_protect_centi,
          action == Action::kFreezePlus ? kFreezeStepCenti : -kFreezeStepCenti);
      if (next != vm_.freeze_protect_centi) {
        vm_.freeze_protect_centi = next;
        refresh_settings_values();
        if (callbacks_.on_freeze_protect_change != nullptr) {
          callbacks_.on_freeze_protect_change(next, callbacks_.ctx);
        }
      }
      break;
    }
    case Action::kNone:
    default:
      break;
  }
}

